alter table app.charges add column if not exists payer_type text not null default 'guardian', add column if not exists payer_name text, add column if not exists player_benefit_id uuid, add column if not exists academy_enrollment_id uuid;
do $$ begin alter table app.charges add constraint charges_payer_type_chk check (payer_type in ('guardian','sponsor','player','organization','other')); exception when duplicate_object then null; end $$;
do $$ begin alter table app.charges add constraint charges_player_benefit_org_fk foreign key (player_benefit_id,organization_id) references app.player_benefits(id,organization_id); exception when duplicate_object then null; end $$;
do $$ begin alter table app.academy_enrollments add constraint academy_enrollments_id_org_uq unique(id,organization_id); exception when duplicate_object then null; end $$;
do $$ begin alter table app.charges add constraint charges_academy_enrollment_org_fk foreign key (academy_enrollment_id,organization_id) references app.academy_enrollments(id,organization_id); exception when duplicate_object then null; end $$;
alter table app.charges drop constraint if exists charges_organization_id_player_id_charge_type_billing_perio_key;
create index if not exists idx_charges_responsibility on app.charges(organization_id,player_id,payer_type,billing_period,status);
create index if not exists idx_charges_academy_enrollment on app.charges(organization_id,academy_enrollment_id) where academy_enrollment_id is not null;
alter table app.player_benefits add column if not exists funding_configured_at timestamptz, add column if not exists funding_configured_by_user_id uuid references auth.users(id);
alter table app.expenses add column if not exists metadata jsonb not null default '{}'::jsonb, add column if not exists production_batch_id uuid, add column if not exists order_id uuid, add column if not exists created_by_user_id uuid references auth.users(id), add column if not exists voided_by_user_id uuid references auth.users(id);
do $$ begin alter table app.expenses add constraint expenses_production_batch_org_fk foreign key (production_batch_id,organization_id) references app.production_batches(id,organization_id); exception when duplicate_object then null; end $$;
do $$ begin alter table app.orders add constraint orders_id_org_uq unique(id,organization_id); exception when duplicate_object then null; end $$;
do $$ begin alter table app.expenses add constraint expenses_order_org_fk foreign key (order_id,organization_id) references app.orders(id,organization_id); exception when duplicate_object then null; end $$;
create index if not exists idx_expenses_production_batch on app.expenses(organization_id,production_batch_id,status) where production_batch_id is not null;
create table if not exists app.charge_adjustment_authorizations(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),charge_id uuid not null,adjustment_type text not null default 'waiver' check(adjustment_type in ('waiver','discount','correction')),amount numeric not null check(amount>0),reason text not null,status text not null default 'approved' check(status in ('approved','consumed','revoked')),authorized_by_user_id uuid not null references auth.users(id),authorized_at timestamptz not null default now(),consumed_by_user_id uuid references auth.users(id),consumed_at timestamptz,revoked_by_user_id uuid references auth.users(id),revoked_at timestamptz,revoke_reason text,idempotency_key text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(id,organization_id),foreign key(charge_id,organization_id) references app.charges(id,organization_id));
create unique index if not exists uq_adjustment_auth_idempotency on app.charge_adjustment_authorizations(organization_id,idempotency_key) where idempotency_key is not null;
create index if not exists idx_adjustment_auth_queue on app.charge_adjustment_authorizations(organization_id,status,authorized_at desc);
alter table app.charge_adjustment_authorizations enable row level security;
revoke all on app.charge_adjustment_authorizations from anon,authenticated,public;
alter table app.charge_adjustments add column if not exists authorization_id uuid, add column if not exists authorized_by_user_id uuid references auth.users(id), add column if not exists posted_by_user_id uuid references auth.users(id), add column if not exists posted_at timestamptz, add column if not exists voided_by_user_id uuid references auth.users(id), add column if not exists voided_at timestamptz, add column if not exists void_reason text;
do $$ begin alter table app.charge_adjustments add constraint charge_adjustments_authorization_fk foreign key (authorization_id,organization_id) references app.charge_adjustment_authorizations(id,organization_id); exception when duplicate_object then null; end $$;
create unique index if not exists uq_charge_adjustments_authorization on app.charge_adjustments(organization_id,authorization_id) where authorization_id is not null;
create or replace function private.is_presidency(p_organization_id uuid) returns boolean language sql stable security definer set search_path='pg_catalog','public' as $$ select exists(select 1 from public.organization_memberships m join public.profiles p on p.user_id=m.user_id and p.active=true where m.organization_id=p_organization_id and m.user_id=(select auth.uid()) and m.active=true and m.role='Presidencia') $$;
create or replace function private.has_financial_config_access(p_organization_id uuid) returns boolean language sql stable security definer set search_path='pg_catalog','public','private' as $$ select private.has_module_access(p_organization_id,'billing',true) and exists(select 1 from public.organization_memberships m where m.organization_id=p_organization_id and m.user_id=(select auth.uid()) and m.active=true and m.role in ('Presidencia','Contabilidad')) $$;
create or replace view app.charge_balances as select c.id,c.organization_id,c.player_id,c.billing_profile_id,c.charge_type,c.billing_period,c.concept,c.amount as base_amount,coalesce(adj.increases,0::numeric) as adjustment_increases,coalesce(adj.decreases,0::numeric) as adjustment_decreases,greatest(0::numeric,c.amount+coalesce(adj.increases,0)-coalesce(adj.decreases,0)) as net_amount,coalesce(pa.allocated_amount,0::numeric) as allocated_amount,greatest(0::numeric,c.amount+coalesce(adj.increases,0)-coalesce(adj.decreases,0)-coalesce(pa.allocated_amount,0)) as balance_due,case when c.status='void' then 'void' when greatest(0::numeric,c.amount+coalesce(adj.increases,0)-coalesce(adj.decreases,0))=0 then 'waived' when coalesce(pa.allocated_amount,0)>=greatest(0::numeric,c.amount+coalesce(adj.increases,0)-coalesce(adj.decreases,0)) then 'paid' when coalesce(pa.allocated_amount,0)>0 then 'partial' else 'pending' end as computed_status,c.due_date,c.late_fee_eligible,c.created_at,c.updated_at,c.payer_type,c.payer_name,c.player_benefit_id,c.academy_enrollment_id from app.charges c left join lateral(select sum(case when a.status='posted' and a.direction='increase' then a.amount else 0 end) increases,sum(case when a.status='posted' and a.direction='decrease' then a.amount else 0 end) decreases from app.charge_adjustments a where a.charge_id=c.id) adj on true left join lateral(select coalesce(sum(a.amount),0) allocated_amount from app.payment_allocations a where a.charge_id=c.id and a.status='posted') pa on true;
create or replace function app.allocate_payment_oldest_first(p_payment_id uuid) returns numeric language plpgsql security definer set search_path to 'app','public' as $$ declare v_payment app.payments%rowtype; r record; v_available numeric; v_piece numeric; v_total numeric:=0; begin select * into v_payment from app.payments where id=p_payment_id for update; if not found or v_payment.status<>'posted' then raise exception 'Payment not available'; end if; if v_payment.payment_purpose<>'billing' then raise exception 'Payment is not a billing payment'; end if; if v_payment.credit_status='legacy_hold' then raise exception 'Legacy held credit requires explicit reconciliation'; end if; for r in select cb.* from app.charge_balances cb where cb.organization_id=v_payment.organization_id and cb.player_id=v_payment.player_id and cb.computed_status in ('pending','partial') and cb.balance_due>0 and ((v_payment.payer_type='sponsor' and cb.payer_type='sponsor' and (cb.payer_name is null or v_payment.payer_name is null or lower(trim(cb.payer_name))=lower(trim(v_payment.payer_name)))) or (coalesce(v_payment.payer_type,'guardian')<>'sponsor' and coalesce(cb.payer_type,'guardian')<>'sponsor')) order by cb.billing_period nulls last,cb.due_date,cb.created_at,cb.id loop select available_credit into v_available from app.payment_balances where id=v_payment.id; exit when coalesce(v_available,0)<=0; v_piece:=least(v_available,r.balance_due); insert into app.payment_allocations(organization_id,payment_id,charge_id,amount) values(v_payment.organization_id,v_payment.id,r.id,v_piece) on conflict(payment_id,charge_id) do update set amount=app.payment_allocations.amount+excluded.amount; v_total:=v_total+v_piece; end loop; return v_total; end $$;
revoke insert,update,delete,truncate,references,trigger on app.charge_adjustment_authorizations,app.charges,app.expenses,app.player_benefits,app.charge_adjustments from public,anon,authenticated;;
